}

// applyTranscriptBackfill replaces a session's transcript, prompts, and skill
// events on the checkpoint's current subtree, returning the new subtree hash.
// Returns ErrCheckpointNotFound when the checkpoint has no sessions yet.
func (s *treeWriter) applyTranscriptBackfill(ctx context.Context, opts UpdateOptions, existing *object.Tree, basePath string) (plumbing.Hash, error) {
	entries, err := s.flattenExisting(existing, basePath)
	if err != nil {
		return plumbing.ZeroHash, err
	}

	rootMetadataPath := checkpointSubtreePath(basePath, paths.MetadataFileName)
	entry, exists := entries[rootMetadataPath]
	if !exists {
		return plumbing.ZeroHash, ErrCheckpointNotFound
	}

	checkpointSummary, err := s.readSummaryFromBlob(entry.Hash)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to read checkpoint summary: %w", err)
	}
	if len(checkpointSummary.Sessions) == 0 {
		return plumbing.ZeroHash, ErrCheckpointNotFound
	}
		},
		func(parentHash plumbing.Hash, existing *object.Tree) (plumbing.Hash, error) {
			checkpointSubtree, err := s.applyTranscriptBackfill(ctx, opts, existing, "")
			if err != nil {
				return plumbing.ZeroHash, err
			}
			authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
			commitMsg := fmt.Sprintf("Finalize transcript for Checkpoint: %s", opts.CheckpointID)
			return CreateCommit(ctx, s.repo, checkpointSubtree, parentHash, commitMsg, authorName, authorEmail)
		},
	)
}

func (s *gitRefsStore) backfillSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error {
	if err := ctx.Err(); err != nil {
		return err //nolint:wrapcheck // Propagating context cancellation
	}

	return s.updateCheckpointRef(ctx, checkpointID,
		func() (plumbing.Hash, *object.Tree, error) {
			return s.refBaseForBackfill(ctx, checkpointID)
		},
		func(parentHash plumbing.Hash, existing *object.Tree) (plumbing.Hash, error) {
			checkpointSubtree, sessionID, err := s.applySummaryBackfill(ctx, existing, "", summary)
			if err != nil {
				return plumbing.ZeroHash, err
			}
			authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
			commitMsg := fmt.Sprintf("Update summary for checkpoint %s (session: %s)", checkpointID, sessionID)
			return CreateCommit(ctx, s.repo, checkpointSubtree, parentHash, commitMsg, authorName, authorEmail)
		},
	)
}

func (s *gitRefsStore) backfillTasks(ctx context.Context, req Tasks) error {
	if err := ctx.Err(); err != nil {
		return err //nolint:wrapcheck // Propagating context cancellation
	}

	return s.updateCheckpointRef(ctx, req.CheckpointID,
		func() (plumbing.Hash, *object.Tree, error) {
			return s.refBaseForBackfill(ctx, req.CheckpointID)
		},
		func(parentHash plumbing.Hash, existing *object.Tree) (plumbing.Hash, error) {
			checkpointSubtree, err := s.applyTasksBackfill(ctx, existing, "", req.Tasks)
			if err != nil {
				return plumbing.ZeroHash, err
			}
			authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
			commitMsg := fmt.Sprintf("Add tasks to checkpoint %s", req.CheckpointID)
			return CreateCommit(ctx, s.repo, checkpointSubtree, parentHash, commitMsg, authorName, authorEmail)
		},
	)
}

